public static class Sprint4ServiceRegistration
{
    public static IServiceCollection AddNotificationsFilesAndJobs(
        this IServiceCollection services, IConfiguration configuration)
    {
        services.AddOptions<EmailOptions>()
            .BindConfiguration(EmailOptions.SectionName)
            .ValidateDataAnnotations()
            .ValidateOnStart();

        services.AddOptions<FileStorageOptions>()
            .BindConfiguration(FileStorageOptions.SectionName)
            .ValidateDataAnnotations()
            .ValidateOnStart();

        services.AddOptions<HangfireDashboardOptions>()
            .BindConfiguration(HangfireDashboardOptions.SectionName)
            .ValidateDataAnnotations()
            .ValidateOnStart();

        var connectionString = configuration.GetConnectionString("Default")
            ?? throw new InvalidOperationException("ConnectionStrings:Default is missing.");

        services.AddHangfire((sp, config) => config
            .SetDataCompatibilityLevel(CompatibilityLevel.Version_180)
            .UseSimpleAssemblyNameTypeSerializer()
            .UseRecommendedSerializerSettings()
            .UseSqlServerStorage(connectionString)
            .UseFilter(new AutomaticRetryAttribute { Attempts = 3 })                       // NTF-04
            .UseFilter(new JobFailureLoggingFilter(sp.GetRequiredService<ILoggerFactory>())));

        services.AddHangfireServer();

        services.AddScoped<IEmailService, MailKitEmailService>();
        services.AddSingleton<IReceiptPdfGenerator, QuestPdfReceiptGenerator>();
        services.AddSingleton<IFileStorage, LocalFileStorage>();
        services.AddScoped<IBackgroundJobScheduler, HangfireJobScheduler>();
        services.AddScoped<IDonationNotificationService, DonationNotificationService>();
        services.AddScoped<DonationMaintenanceJobs>();
        services.AddScoped<ExpireCampaignsJob>();

        return services;
    }
}

