namespace DonationHub.Infrastructure.Jobs;

public sealed class JobFailureLoggingFilter(ILoggerFactory loggerFactory) : IServerFilter
{
    private readonly ILogger _logger = loggerFactory.CreateLogger("DonationHub.Jobs");

    public void OnPerforming(PerformingContext context) =>
        _logger.LogInformation("Job {JobId} ({JobName}) started",
            context.BackgroundJob.Id, JobName(context));

    public void OnPerformed(PerformedContext context)
    {
        if (context.Exception is null)
        {
            _logger.LogInformation("Job {JobId} ({JobName}) succeeded",
                context.BackgroundJob.Id, JobName(context));
            return;
        }

        // كل محاولة فاشلة = Error. AutomaticRetry يقرر بعدها إعادة الجدولة أو Failed.
        _logger.LogError(context.Exception, "Job {JobId} ({JobName}) failed",
            context.BackgroundJob.Id, JobName(context));
    }

    private static string JobName(PerformContext context) =>
        $"{context.BackgroundJob.Job.Type.Name}.{context.BackgroundJob.Job.Method.Name}";
}

using System.Net.Http.Headers;
using System.Security.Cryptography;
using System.Text;
using DonationHub.Infrastructure.Options;
using Hangfire.Dashboard;

namespace DonationHub.Api.Infrastructure;

public sealed class BasicAuthDashboardFilter(HangfireDashboardOptions options) : IDashboardAuthorizationFilter
{
    public bool Authorize(DashboardContext context)
    {
        var http = context.GetHttpContext();
        var header = http.Request.Headers.Authorization.ToString();

        if (AuthenticationHeaderValue.TryParse(header, out var auth)
            && string.Equals(auth.Scheme, "Basic", StringComparison.OrdinalIgnoreCase)
            && auth.Parameter is not null
            && CredentialsMatch(auth.Parameter))
        {
            return true;
        }

        http.Response.Headers.WWWAuthenticate = "Basic realm=\"DonationHub Jobs\"";
        return false;
    }

    private bool CredentialsMatch(string encoded)
    {
        string decoded;
        try
        {
            decoded = Encoding.UTF8.GetString(Convert.FromBase64String(encoded));
        }
        catch (FormatException)
        {
            return false;
        }

        var separator = decoded.IndexOf(':');
        if (separator < 0)
            return false;

        // & وليس && حتى نقارن الاثنين دائمًا (زمن ثابت)
        return SecureEquals(decoded[..separator], options.Username)
             & SecureEquals(decoded[(separator + 1)..], options.Password);
    }

    private static bool SecureEquals(string actual, string expected) =>
        CryptographicOperations.FixedTimeEquals(
            SHA256.HashData(Encoding.UTF8.GetBytes(actual)),
            SHA256.HashData(Encoding.UTF8.GetBytes(expected)));
}

