using DonationHub.Application.Abstractions;
using DonationHub.Infrastructure.Options;
using MailKit.Security;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;
using MimeKit;

namespace DonationHub.Infrastructure.Email;

public sealed class MailKitEmailService(
    IOptions<EmailOptions> options,
    ILogger<MailKitEmailService> logger) : IEmailService
{
    public async Task SendAsync(EmailMessage message, CancellationToken ct = default)
    {
        var settings = options.Value;

        var mime = new MimeMessage();
        mime.From.Add(new MailboxAddress(settings.SenderName, settings.SenderEmail));
        mime.To.Add(new MailboxAddress(message.ToName, message.ToEmail));
        mime.Subject = message.Subject;

        var body = new BodyBuilder { HtmlBody = message.HtmlBody };
        foreach (var attachment in message.Attachments)
            body.Attachments.Add(attachment.FileName, attachment.Content, ContentType.Parse(attachment.ContentType));
        mime.Body = body.ToMessageBody();

        using var smtp = new MailKit.Net.Smtp.SmtpClient();
        var security = settings.UseStartTls ? SecureSocketOptions.StartTls : SecureSocketOptions.None;
        await smtp.ConnectAsync(settings.Host, settings.Port, security, ct);

        if (!string.IsNullOrWhiteSpace(settings.Username))
            await smtp.AuthenticateAsync(settings.Username, settings.Password, ct);

        await smtp.SendAsync(mime, ct);
        await smtp.DisconnectAsync(true, ct);

        // لا نسجّل العنوان الكامل ولا بيانات SMTP — الموضوع وعدد المرفقات يكفيان للتتبع
        logger.LogInformation("Email \"{Subject}\" sent with {AttachmentCount} attachment(s)",
            message.Subject, message.Attachments.Count);
    }
}

