    public static EmailContent DonationReceipt(string language, string donorName, string campaignTitle,
        string receiptNumber, decimal amount, string currency)
    {
        var ar = IsArabic(language);
        var money = FormatMoney(amount, currency, ar);

        return ar
            ? new EmailContent($"إيصال تبرعك رقم {receiptNumber}", Layout(ar,
                $"<p>مرحبًا {E(donorName)}،</p><p>شكرًا لتبرعك بمبلغ <strong>{money}</strong> لحملة «{E(campaignTitle)}». تجد الإيصال مرفقًا بهذه الرسالة.</p>"))
            : new EmailContent($"Your donation receipt {receiptNumber}", Layout(ar,
                $"<p>Hello {E(donorName)},</p><p>Thank you for donating <strong>{money}</strong> to \"{E(campaignTitle)}\". Your receipt is attached.</p>"));
    }

    public static EmailContent GoalReached(string language, string ownerName, string campaignTitle,
        decimal goalAmount, string currency)
    {
        var ar = IsArabic(language);
        var money = FormatMoney(goalAmount, currency, ar);

        return ar
            ? new EmailContent("🎉 حملتك وصلت إلى هدفها", Layout(ar,
                $"<p>مرحبًا {E(ownerName)}،</p><p>حملة «{E(campaignTitle)}» وصلت إلى هدفها ({money}). شكرًا لك!</p>"))
            : new EmailContent("🎉 Your campaign reached its goal", Layout(ar,
                $"<p>Hello {E(ownerName)},</p><p>\"{E(campaignTitle)}\" reached its goal of {money}. Thank you!</p>"));
    }

    private static string Layout(bool ar, string content)
    {
        var dir = ar ? "rtl" : "ltr";
        var lang = ar ? "ar" : "en";
        var align = ar ? "right" : "left";

        return $"""
            <!DOCTYPE html>
            <html dir="{dir}" lang="{lang}">
            <head><meta charset="utf-8"></head>
            <body style="font-family: Tahoma, Arial, sans-serif; text-align: {align};">
            {content}
            <hr><p style="color:#888;font-size:12px">DonationHub</p>
            </body>
            </html>
            """;
    }

    private static bool IsArabic(string language) =>
        string.Equals(language, "ar", StringComparison.OrdinalIgnoreCase);

    private static string FormatMoney(decimal amount, string currency, bool ar) =>
        $"{amount.ToString("N2", CultureInfo.GetCultureInfo(ar ? "ar-EG" : "en-US"))} {currency}";

    private static string E(string value) => WebUtility.HtmlEncode(value);
}

