namespace DonationHub.Infrastructure.Receipts;

public sealed class QuestPdfReceiptGenerator : IReceiptPdfGenerator
{
    public byte[] Generate(ReceiptData data)
    {
        var ar = data.Language == "ar";
        var culture = CultureInfo.GetCultureInfo(ar ? "ar-EG" : "en-US");
        var t = ar ? Arabic : English;

        return Document.Create(container =>
        {
            container.Page(page =>
            {
                page.Size(PageSizes.A4);
                page.Margin(2, Unit.Centimetre);
                page.DefaultTextStyle(x => x.FontSize(11).FontFamily(ar ? "Noto Naskh Arabic" : "Lato"));
                if (ar)
                    page.ContentFromRightToLeft();

                page.Header().Column(column =>
                {
                    column.Item().Text("DonationHub").FontSize(22).Bold().FontColor(Colors.Blue.Darken2);
                    column.Item().Text(t.VerifiedOrganization).FontSize(10).FontColor(Colors.Grey.Darken1);
                    column.Item().PaddingTop(8).LineHorizontal(1).LineColor(Colors.Grey.Lighten1);
                });

                page.Content().PaddingVertical(20).Column(column =>
                {
                    column.Spacing(12);
                    column.Item().Text(t.Title).FontSize(18).SemiBold();

                    column.Item().Table(table =>
                    {
                        table.ColumnsDefinition(columns =>
                        {
                            columns.ConstantColumn(160);
                            columns.RelativeColumn();
                        });

                        void Row(string label, string value)
                        {
                            table.Cell().BorderBottom(1).BorderColor(Colors.Grey.Lighten2).PaddingVertical(6).Text(label).SemiBold();
                            table.Cell().BorderBottom(1).BorderColor(Colors.Grey.Lighten2).PaddingVertical(6).Text(value);
                        }

                        Row(t.ReceiptNumber, data.ReceiptNumber);
                        Row(t.Date, data.TransactionDateUtc.ToString("dd MMMM yyyy, HH:mm 'UTC'", culture));
                        Row(t.Campaign, data.CampaignTitle);
                        Row(t.Category, data.CategoryName);
                        Row(t.Donor, data.DonorName);
                        Row(t.Amount, $"{data.Amount.ToString("N2", culture)} {data.Currency}");
                    });

                    column.Item().PaddingTop(10).Text(t.ThankYou).Italic();
                });

                page.Footer().Column(column =>
                {
                    column.Item().AlignCenter().Text(t.Footer).FontSize(9).FontColor(Colors.Grey.Darken1);
                    column.Item().AlignCenter().Text(text =>
                    {
                        text.CurrentPageNumber();
                        text.Span(" / ");
                        text.TotalPages();
                    });
                });
            });
        }).GeneratePdf();
    }

    private sealed record Labels(string Title, string VerifiedOrganization, string ReceiptNumber, string Date,
        string Campaign, string Category, string Donor, string Amount, string ThankYou, string Footer);

    private static readonly Labels English = new("Donation Receipt", "Verified non-profit organization",
        "Receipt number", "Transaction date", "Campaign", "Category", "Donor", "Amount",
        "Thank you for your generosity.", "This receipt was generated electronically by DonationHub and needs no signature.");

