public sealed record GetDonationReceiptQuery(Guid DonationId) : IRequest<Result<ReceiptFile>>;

public sealed record ReceiptFile(Stream Content, string FileName);

public sealed class GetDonationReceiptQueryHandler(
    IReadDbContext readDb, IFileStorage fileStorage, ICurrentUser currentUser)
    : IRequestHandler<GetDonationReceiptQuery, Result<ReceiptFile>>
{
    public async Task<Result<ReceiptFile>> Handle(GetDonationReceiptQuery request, CancellationToken ct)
    {
        var userId = currentUser.UserId;                       // ICurrentUser من Sprint 3
        var isAdmin = currentUser.IsInRole(Roles.Admin);

        var donation = await readDb.Donations
            .Where(d => d.Id == request.DonationId && (isAdmin || d.DonorUserId == userId))
            .Select(d => new { d.ReceiptNumber, d.ReceiptFileName })
            .SingleOrDefaultAsync(ct);

        if (donation is null)
            return Result<ReceiptFile>.Failure(DonationErrors.NotFound);       // ليس لك = غير موجود

        if (donation.ReceiptFileName is null)
            return Result<ReceiptFile>.Failure(DonationErrors.ReceiptNotReady); // الـ job لم ينتهِ بعد

        var stream = await fileStorage.OpenReadAsync(FileFolders.Receipts, donation.ReceiptFileName, ct);
        return stream is null
            ? Result<ReceiptFile>.Failure(DonationErrors.ReceiptNotReady)
            : Result<ReceiptFile>.Success(new ReceiptFile(stream, $"{donation.ReceiptNumber}.pdf"));
    }
}

