namespace DonationHub.Application.Common.Files;

public static class FileSignatureValidator
{
    public const int HeaderLength = 12;

    private static ReadOnlySpan<byte> Jpeg => [0xFF, 0xD8, 0xFF];
    private static ReadOnlySpan<byte> Png => [0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A];
    private static ReadOnlySpan<byte> Riff => "RIFF"u8;
    private static ReadOnlySpan<byte> Webp => "WEBP"u8;

    /// <summary>يُرجع الامتداد الحقيقي حسب المحتوى، أو null إذا لم يكن صورة مسموحة.</summary>
    public static string? DetectImageExtension(ReadOnlySpan<byte> header)
    {
        if (header.StartsWith(Jpeg))
            return ".jpg";

        if (header.StartsWith(Png))
            return ".png";

        // RIFF <4 bytes size> WEBP
        if (header.Length >= HeaderLength
            && header[..4].SequenceEqual(Riff)
            && header.Slice(8, 4).SequenceEqual(Webp))
            return ".webp";

        return null;
    }
}

