namespace DonationHub.Infrastructure.Files;

public sealed class LocalFileStorage : IFileStorage
{
    private readonly FileStorageOptions _options;
    private readonly string _root;

    public LocalFileStorage(IOptions<FileStorageOptions> options, IHostEnvironment environment)
    {
        _options = options.Value;
        _root = Path.GetFullPath(Path.Combine(environment.ContentRootPath, _options.RootPath));
    }

    public async Task<string> SaveAsync(string folder, Stream content, string extension, CancellationToken ct = default)
    {
        var fileName = $"{Guid.NewGuid():N}{extension}";               // FIL-03
        var path = ResolvePath(folder, fileName);
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);

        await using var file = new FileStream(path, FileMode.CreateNew, FileAccess.Write,
            FileShare.None, bufferSize: 81920, useAsync: true);
        await content.CopyToAsync(file, ct);
        return fileName;
    }

    public Task<Stream?> OpenReadAsync(string folder, string fileName, CancellationToken ct = default)
    {
        var path = ResolvePath(folder, fileName);
        Stream? stream = File.Exists(path)
            ? new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.Read, bufferSize: 81920, useAsync: true)
            : null;
        return Task.FromResult(stream);
    }

    public Task DeleteAsync(string folder, string fileName, CancellationToken ct = default)
    {
        var path = ResolvePath(folder, fileName);
        if (File.Exists(path))
            File.Delete(path);
        return Task.CompletedTask;
    }

    public string GetPublicUrl(string folder, string fileName) =>
        folder == FileFolders.Banners
            ? $"{_options.PublicBannersPath}/{fileName}"
            : throw new InvalidOperationException($"Folder '{folder}' is not public.");

    private string ResolvePath(string folder, string fileName)
    {
        // يمنع path traversal مثل ../../appsettings.json حتى لو وصل اسم من مصدر غير متوقع
        if (fileName != Path.GetFileName(fileName))
            throw new ArgumentException("Invalid file name.", nameof(fileName));

        return Path.Combine(_root, folder, fileName);
    }
}

