namespace DonationHub.Application.Features.Campaigns.UploadBanner;

public sealed record UploadCampaignBannerCommand(
    Guid CampaignId, Stream Content, long Length) : IRequest<Result<string>>;

public sealed class UploadCampaignBannerCommandHandler(
    IUnitOfWork unitOfWork,
    ICampaignAuthorizer campaignAuthorizer,        // Sprint 3: Admin أو المالك
    IFileStorage fileStorage,
    ICacheService cache,
    IOptions<FileStorageOptions> options,
    TimeProvider timeProvider,
    ILogger<UploadCampaignBannerCommandHandler> logger)
    : IRequestHandler<UploadCampaignBannerCommand, Result<string>>
{
    public async Task<Result<string>> Handle(UploadCampaignBannerCommand request, CancellationToken ct)
    {
        var campaign = await unitOfWork.Repository<Campaign>().GetByIdAsync(request.CampaignId, ct);
        if (campaign is null || !await campaignAuthorizer.CanManageAsync(campaign))
            return Result<string>.Failure(CampaignErrors.NotFound);              // ليست لك = غير موجودة

        var maxBytes = options.Value.MaxBannerSizeBytes;
        if (request.Length > maxBytes)
            return Result<string>.Failure(FileErrors.TooLarge);                  // 413

        using var buffer = new MemoryStream(capacity: (int)request.Length);
        await request.Content.CopyToAsync(buffer, ct);
        if (buffer.Length > maxBytes)                                             // لا نثق بـ Length أيضًا
            return Result<string>.Failure(FileErrors.TooLarge);

        var extension = FileSignatureValidator.DetectImageExtension(
            buffer.GetBuffer().AsSpan(0, (int)buffer.Length));
        if (extension is null)
        {
            logger.LogWarning("Rejected banner for campaign {CampaignId}: invalid file signature", request.CampaignId);
            return Result<string>.Failure(FileErrors.InvalidType);                // 400
        }

        buffer.Position = 0;
        var newFileName = await fileStorage.SaveAsync(FileFolders.Banners, buffer, extension, ct);
        var oldFileName = campaign.BannerFileName;
        campaign.SetBanner(newFileName, timeProvider.GetUtcNow().UtcDateTime);

        try
        {
            await unitOfWork.SaveChangesAsync(ct);
        }
        catch
        {
            await fileStorage.DeleteAsync(FileFolders.Banners, newFileName, CancellationToken.None);
            throw;
        }

        if (oldFileName is not null)
            await fileStorage.DeleteAsync(FileFolders.Banners, oldFileName, ct);   // FIL-04

        await cache.InvalidateCampaignAsync(campaign.Id, ct);                     // Sprint 3: bannerUrl تغيّر

        logger.LogInformation("Banner {FileName} set for campaign {CampaignId}", newFileName, campaign.Id);
        return Result<string>.Success(fileStorage.GetPublicUrl(FileFolders.Banners, newFileName));
    }
}

