{
    public void EnqueueDonationReceipt(Guid donationId) =>
        jobs.Enqueue<IDonationNotificationService>(s => s.SendReceiptAsync(donationId, CancellationToken.None));

    public void EnqueueGoalReachedEmail(Guid campaignId) =>
