// DonationSuccessFlow (Sprint 3) — نفس الكلاس ونفس حلقة إعادة المحاولة على RowVersion.
// الجديد فقط (مُعلَّم بـ «Sprint 4»): IBackgroundJobScheduler في الـ constructor، و wasActive، والجدولة بعد الـ commit.
public sealed class DonationSuccessFlow(
    IUnitOfWork unitOfWork,
    IReceiptNumberGenerator receiptNumbers,
    ICacheService cache,
    IBackgroundJobScheduler jobs,                                         // Sprint 4
    TimeProvider clock,
    ILogger<DonationSuccessFlow> logger) : IDonationSuccessFlow
{
    private const int MaxAttempts = 3;

    public async Task<Result<DonationResponse>> ExecuteAsync(Guid donationId, CancellationToken ct)
    {
        string? receiptNumber = null;

        for (var attempt = 1; attempt <= MaxAttempts; attempt++)
        {
            var donation = await unitOfWork.Repository<Donation>().GetByIdAsync(donationId, ct);
            if (donation is null) return DonationErrors.NotFound;
            if (donation.Status != DonationStatus.Pending) return DonationErrors.InvalidState;   // 409

            var campaign = await unitOfWork.Repository<Campaign>().GetByIdAsync(donation.CampaignId, ct);
            if (campaign is null) return CampaignErrors.NotFound;

            var now = clock.GetUtcNow().UtcDateTime;
            if (campaign.Status != CampaignStatus.Active || campaign.EndDate <= now)
            {
                logger.LogWarning(
                    "Late payment: donation {DonationId} succeeded after campaign {CampaignId} became {Status}",
                    donation.Id, campaign.Id, campaign.Status);
            }

            var wasActive = campaign.Status == CampaignStatus.Active;           // Sprint 4: لنعرف «اكتملت للتو»
            receiptNumber ??= await receiptNumbers.NextAsync(now, ct);          // رقم واحد يُعاد استخدامه في المحاولات
            donation.MarkSucceeded(campaign, receiptNumber, now);

            try
            {
                await unitOfWork.SaveChangesAsync(ct);                          // ← الـ commit
            }
            catch (DbUpdateConcurrencyException)
            {
                logger.LogInformation("Concurrency conflict on campaign {CampaignId}, attempt {Attempt}",
                    campaign.Id, attempt);
                unitOfWork.ClearChangeTracker();
                continue;                                                       // لم يُحفظ شيء ← لم يُجدوَل شيء
            }

            // ===== Sprint 4: بعد الـ commit فقط، والوسائط معرّفات فقط =====
            jobs.EnqueueDonationReceipt(donation.Id);                           // JOB-01
            if (wasActive && campaign.Status == CampaignStatus.Completed)
                jobs.EnqueueGoalReachedEmail(campaign.Id);                      // JOB-02

            logger.LogInformation("Donation {DonationId} succeeded with receipt {ReceiptNumber}",
                donation.Id, receiptNumber);
            await cache.InvalidateCampaignAsync(campaign.Id, ct);               // كما في Sprint 3
            return DonationResponse.From(donation);
        }

        return CampaignErrors.ConcurrencyConflict;                              // 409 بعد استنفاد المحاولات
    }
}

