namespace DonationHub.Application.Features.Donations.FailStalePending;

public sealed record FailStalePendingDonationCommand(Guid DonationId) : IRequest<Result>;

public sealed class FailStalePendingDonationCommandHandler(
    IUnitOfWork unitOfWork,
    TimeProvider timeProvider,
    ILogger<FailStalePendingDonationCommandHandler> logger)
    : IRequestHandler<FailStalePendingDonationCommand, Result>
{
    public const string TimeoutReason = "PendingTimeout";

    public async Task<Result> Handle(FailStalePendingDonationCommand request, CancellationToken ct)
    {
        var donation = await unitOfWork.Repository<Donation>().GetByIdAsync(request.DonationId, ct);

        if (donation is null)
        {
            logger.LogWarning("Stale-pending check: donation {DonationId} not found", request.DonationId);
            return Result.Success();
        }

        if (donation.Status != DonationStatus.Pending)
        {
            logger.LogInformation("Stale-pending check: donation {DonationId} is already {Status}; nothing to do",
                donation.Id, donation.Status);
            return Result.Success();                         // idempotent
        }

        donation.MarkFailed(TimeoutReason, timeProvider.GetUtcNow().UtcDateTime);
        await unitOfWork.SaveChangesAsync(ct);

        logger.LogInformation("Donation {DonationId} failed after the pending timeout", donation.Id);
        return Result.Success();
    }
}

