namespace DonationHub.Infrastructure.Jobs;

public sealed class DonationNotificationService(
    AppDbContext db,
    IReceiptPdfGenerator pdfGenerator,
    IFileStorage fileStorage,
    IEmailService emailService,
    IOptions<DonationOptions> donationOptions,
    TimeProvider timeProvider,
    ILogger<DonationNotificationService> logger) : IDonationNotificationService
{
    public async Task SendReceiptAsync(Guid donationId, CancellationToken ct)
    {
        var donation = await db.Donations.SingleOrDefaultAsync(d => d.Id == donationId, ct);
        if (donation is null || donation.Status != DonationStatus.Succeeded)
        {
            logger.LogWarning("Receipt job skipped: donation {DonationId} is missing or not succeeded", donationId);
            return;
        }

        if (donation.ReceiptSentAt is not null)
        {
            logger.LogInformation("Receipt for donation {DonationId} was already sent; skipping", donationId);
            return;                                                         // idempotent
        }

        var info = await (
            from c in db.Campaigns.IgnoreQueryFilters()                      // الحملة قد تكون محذوفة ناعمًا
            join cat in db.Categories on c.CategoryId equals cat.Id
            from u in db.Users
            where c.Id == donation.CampaignId && u.Id == donation.DonorUserId
            select new { u.Email, u.FullName, u.PreferredLanguage, c.TitleAr, c.TitleEn, cat.NameAr, cat.NameEn })
            .AsNoTracking()
            .SingleAsync(ct);

        var ar = info.PreferredLanguage == "ar";
        var currency = donationOptions.Value.DefaultCurrency;
        var campaignTitle = ar ? info.TitleAr : info.TitleEn;

        // الخطوة 1: PDF مرة واحدة فقط (FIL-06)
        if (donation.ReceiptFileName is null)
        {
            var pdf = pdfGenerator.Generate(new ReceiptData(
                donation.ReceiptNumber!, donation.CompletedAt!.Value, campaignTitle,
                ar ? info.NameAr : info.NameEn, info.FullName, donation.Amount, currency, info.PreferredLanguage));

            using var pdfStream = new MemoryStream(pdf);
            var fileName = await fileStorage.SaveAsync(FileFolders.Receipts, pdfStream, ".pdf", ct);
            donation.AttachReceipt(fileName);
            await db.SaveChangesAsync(ct);
        }

        // الخطوة 2: البريد مع المرفق (NTF-02, NTF-05)
        byte[] attachment;
        await using (var stored = await fileStorage.OpenReadAsync(FileFolders.Receipts, donation.ReceiptFileName!, ct)
            ?? throw new InvalidOperationException($"Receipt file for donation {donationId} is missing."))
        {
            using var buffer = new MemoryStream();
            await stored.CopyToAsync(buffer, ct);
            attachment = buffer.ToArray();
        }

        var content = EmailTemplates.DonationReceipt(info.PreferredLanguage, info.FullName, campaignTitle,
            donation.ReceiptNumber!, donation.Amount, currency);

        await emailService.SendAsync(new EmailMessage(info.Email!, info.FullName, content.Subject, content.HtmlBody,
            [new EmailAttachment($"{donation.ReceiptNumber}.pdf", attachment, "application/pdf")]), ct);

        donation.MarkReceiptSent(timeProvider.GetUtcNow().UtcDateTime);
        await db.SaveChangesAsync(ct);

        logger.LogInformation("Receipt {ReceiptNumber} emailed for donation {DonationId}",
            donation.ReceiptNumber, donationId);
    }

    public async Task SendGoalReachedAsync(Guid campaignId, CancellationToken ct)
    {
        var campaign = await db.Campaigns.IgnoreQueryFilters().SingleOrDefaultAsync(c => c.Id == campaignId, ct);
        if (campaign is null || campaign.Status != CampaignStatus.Completed || campaign.GoalEmailSentAt is not null)
        {
            logger.LogInformation("Goal-reached email for campaign {CampaignId} not needed; skipping", campaignId);
            return;                                                         // idempotent
        }

        var owner = await db.Users.AsNoTracking()
            .Where(u => u.Id == campaign.CreatedByUserId)
            .Select(u => new { u.Email, u.FullName, u.PreferredLanguage })
            .SingleAsync(ct);

        var content = EmailTemplates.GoalReached(owner.PreferredLanguage, owner.FullName,
            owner.PreferredLanguage == "ar" ? campaign.TitleAr : campaign.TitleEn,
            campaign.GoalAmount, donationOptions.Value.DefaultCurrency);

        await emailService.SendAsync(new EmailMessage(owner.Email!, owner.FullName, content.Subject, content.HtmlBody, []), ct);

        campaign.MarkGoalEmailSent(timeProvider.GetUtcNow().UtcDateTime);
        await db.SaveChangesAsync(ct);

        logger.LogInformation("Goal-reached email sent for campaign {CampaignId}", campaignId);
    }
}

