namespace DonationHub.Infrastructure.Jobs;

public sealed class ExpireCampaignsJob(
    AppDbContext db, ICacheService cache, TimeProvider timeProvider, ILogger<ExpireCampaignsJob> logger)
{
    private const int BatchSize = 200;

    public async Task RunAsync(CancellationToken ct)
    {
        var utcNow = timeProvider.GetUtcNow().UtcDateTime;
        var expiredCount = 0;

        while (!ct.IsCancellationRequested)
        {
            var batch = await db.Campaigns
                .Where(c => c.Status == CampaignStatus.Active && c.EndDate <= utcNow)
                .OrderBy(c => c.EndDate)
                .Take(BatchSize)
                .ToListAsync(ct);

            if (batch.Count == 0)
                break;

            foreach (var campaign in batch)
                campaign.MarkExpiredIfDue(utcNow);

            try
            {
                await db.SaveChangesAsync(ct);
                expiredCount += batch.Count;

                // CMP-09: تغيّر الحالة إلى Expired يُبطل كاش الحملة والقوائم — بعد نجاح الحفظ فقط
                foreach (var campaign in batch)
                    await cache.InvalidateCampaignAsync(campaign.Id, ct);
            }
            catch (DbUpdateConcurrencyException ex)
            {
                // تبرع نجح على إحدى الحملات في نفس اللحظة — التشغيل القادم (بعد ساعة) يكمل
                logger.LogWarning(ex, "Concurrency conflict while expiring campaigns; remaining ones will be retried next run");
                break;
            }
            finally
            {
                db.ChangeTracker.Clear();
            }
        }

        logger.LogInformation("Expire-campaigns job marked {ExpiredCount} campaign(s) as Expired", expiredCount);
    }
}

